<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{createDepartment,getDepartmentsAdmin,updateDepartment}from'../../services/admin';import type{Department}from'../../types/medical'
const rows=ref<Department[]>([]),loading=ref(false),dialog=ref(false),saving=ref(false),current=ref<Department|null>(null),form=reactive({name:'',description:''})
async function load(){loading.value=true;try{rows.value=(await getDepartmentsAdmin()).results}catch{rows.value=[]}finally{loading.value=false}}
function open(row?:Department){current.value=row||null;Object.assign(form,{name:row?.name||'',description:row?.description||''});dialog.value=true}
async function submit(){if(!form.name.trim()){ElMessage.warning('科室名称不能为空');return}saving.value=true;try{current.value?await updateDepartment(current.value.id,form):await createDepartment(form);ElMessage.success('科室信息已保存');dialog.value=false;await load()}catch(e:any){ElMessage.error(e.response?.data?.detail||'保存失败')}finally{saving.value=false}}
async function toggle(row:Department){await updateDepartment(row.id,{status:row.status==='active'?'inactive':'active'});await load()}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">DEPARTMENT DIRECTORY</p><h1>科室管理</h1><p>维护科室名称、介绍和启用状态</p></div><el-button type="primary" @click="open()">＋ 新增科室</el-button></div><div class="department-grid" v-loading="loading"><el-card v-for="row in rows" :key="row.id"><div class="department-head"><h3>{{row.name}}</h3><el-tag :type="row.status==='active'?'success':'info'">{{row.status==='active'?'启用':'停用'}}</el-tag></div><p>{{row.description||'暂无科室介绍'}}</p><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link :type="row.status==='active'?'danger':'success'" @click="toggle(row)">{{row.status==='active'?'停用':'启用'}}</el-button></el-card></div><el-dialog v-model="dialog" :title="current?'编辑科室':'新增科室'" width="min(520px,94vw)"><el-form label-position="top"><el-form-item label="科室名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="科室介绍"><el-input v-model="form.description" type="textarea" :rows="5" maxlength="500" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">保存</el-button></template></el-dialog></section></template>
